_choice_attr() {
    mdimport -A 2>/dev/null | gawk -F'\t\t' '
        BEGIN { sq = "\047" }
        {
            name = $1
            desc = $3
            sub("^" sq, "", name)
            sub(sq "$", "", name)
            sub("^" sq, "", desc)
            sub(sq "$", "", desc)
            if (desc == "(null)") {
                desc = ""
            }
            print name "\t" desc
        }
    '
}
